//! Per-command help. Flags and the one-line description for each command.

pub fn command_help(command: &str) -> Option<String> {
    let (usage, about, flags) = match command {
        "serve" => ("serve [--port N] [--host ADDR] [--auth-token TOKEN] [--no-auth]", "HTTP server for the dashboard and POST /call", &["--port", "--host", "--auth-token", "--no-auth"][..]),
        "serve-mcp" => ("serve-mcp", "MCP server on stdin and stdout", &[][..]),
        "serve-sse" => ("serve-sse [--port N] [--host ADDR] [--no-auth]", "Dashboard server", &["--port", "--host", "--auth-token", "--no-auth"][..]),
        "status" => ("status", "Print hub counts", &[][..]),
        "register" => ("register AGENT_ID [--parent-id ID] [--graph-agent-id ID] [--worktree-root PATH]", "Register an agent", &["--parent-id", "--graph-agent-id", "--worktree-root"][..]),
        "heartbeat" => ("heartbeat AGENT_ID", "Record a heartbeat", &[][..]),
        "deregister" => ("deregister AGENT_ID", "Stop an agent and release its locks", &[][..]),
        "list-agents" => ("list-agents [--all] [--stale-timeout SECONDS]", "List agents", &["--all", "--stale-timeout"][..]),
        "agent-relations" => ("agent-relations AGENT_ID [--mode lineage]", "Show lineage or siblings", &["--mode"][..]),
        "acquire-lock" => ("acquire-lock PATH AGENT_ID [--lock-type TYPE] [--ttl SECONDS] [--force] [--region-start N] [--region-end N] [--retry] [--max-retries N] [--backoff-ms N] [--timeout-ms N]", "Lock a document", &["--lock-type", "--ttl", "--force", "--region-start", "--region-end", "--retry", "--max-retries", "--backoff-ms", "--timeout-ms"][..]),
        "release-lock" => ("release-lock PATH AGENT_ID [--region-start N] [--region-end N]", "Release a lock", &["--region-start", "--region-end"][..]),
        "refresh-lock" => ("refresh-lock PATH AGENT_ID [--ttl SECONDS] [--region-start N] [--region-end N]", "Refresh a lock", &["--ttl", "--region-start", "--region-end"][..]),
        "lock-status" => ("lock-status PATH", "Show whether a path is locked", &[][..]),
        "list-locks" => ("list-locks [--agent-id ID]", "List active locks", &["--agent-id"][..]),
        "admin-locks" => ("admin-locks ACTION [--agent-id ID] [--grace-seconds N] [--timeout N]", "Release, reap expired locks, or reap stale agents", &["--agent-id", "--grace-seconds", "--timeout"][..]),
        "broadcast" => ("broadcast AGENT_ID [--document-path PATH] [--handoff-targets ID ...] [--require-ack] [--message TEXT]", "Broadcast or record a handoff", &["--document-path", "--handoff-targets", "--require-ack", "--message"][..]),
        "acknowledge-broadcast" => ("acknowledge-broadcast BROADCAST_ID AGENT_ID", "Acknowledge a broadcast", &[][..]),
        "wait-for-broadcast-acks" => ("wait-for-broadcast-acks BROADCAST_ID [--timeout SECONDS]", "Wait for broadcast acknowledgements", &["--timeout"][..]),
        "acknowledge-handoff" => ("acknowledge-handoff HANDOFF_ID AGENT_ID", "Acknowledge a handoff", &[][..]),
        "complete-handoff" => ("complete-handoff HANDOFF_ID", "Complete a handoff", &[][..]),
        "cancel-handoff" => ("cancel-handoff HANDOFF_ID", "Cancel a handoff", &[][..]),
        "get-handoffs" => ("get-handoffs [--status STATUS] [--from-agent-id ID] [--limit N]", "List handoffs", &["--status", "--from-agent-id", "--limit"][..]),
        "wait-for-handoff" => ("wait-for-handoff HANDOFF_ID [--timeout SECONDS] [--mode MODE]", "Wait for a handoff", &["--timeout", "--mode"][..]),
        "wait-for-locks" => ("wait-for-locks AGENT_ID PATH ... [--timeout SECONDS]", "Wait until paths are free", &["--timeout"][..]),
        "notify-change" => ("notify-change PATH CHANGE_TYPE AGENT_ID", "Record a document change", &[][..]),
        "get-notifications" => ("get-notifications [--since TIME] [--exclude-agent ID] [--limit N]", "List change notifications", &["--since", "--exclude-agent", "--limit"][..]),
        "prune-notifications" => ("prune-notifications [--max-age SECONDS] [--max-entries N]", "Delete old notifications", &["--max-age", "--max-entries"][..]),
        "wait-for-notifications" => ("wait-for-notifications AGENT_ID [--timeout SECONDS] [--poll-interval SECONDS] [--exclude-agent ID]", "Wait for notifications from the last second", &["--timeout", "--poll-interval", "--exclude-agent"][..]),
        "get-conflicts" => ("get-conflicts [--document-path PATH] [--agent-id ID] [--limit N]", "List lock conflicts", &["--document-path", "--agent-id", "--limit"][..]),
        "contention-hotspots" => ("contention-hotspots [--limit N]", "Rank paths by conflict count", &["--limit"][..]),
        "load-spec" => ("load-spec [PATH]", "Load a coordination spec", &[][..]),
        "validate-spec" => ("validate-spec", "Validate the loaded coordination spec", &[][..]),
        "scan-project" => ("scan-project [--worktree-root PATH] [--extensions EXT ...]", "Scan files and assign ownership", &["--worktree-root", "--extensions"][..]),
        "dashboard" => ("dashboard", "Print agents, locks, and tasks", &[][..]),
        "agent-status" => ("agent-status AGENT_ID [--tree]", "Print one agent's status", &["--tree"][..]),
        "agent-tree" => ("agent-tree [AGENT_ID]", "Print the agent tree", &[][..]),
        "assess" => ("assess [--suite PATH] [--format markdown] [--graph-agent-id ID] [--output PATH]", "Score a coordination session", &["--suite", "--format", "--graph-agent-id", "--output"][..]),
        "doctor" => ("doctor", "Check the install", &[][..]),
        "init" => ("init [--auto-dashboard] [--monitor-skill]", "Create storage and write hook config", &["--auto-dashboard", "--monitor-skill"][..]),
        "auto-start-dashboard" => ("auto-start-dashboard [--host ADDR] [--port N]", "Start the dashboard if the port is free", &["--host", "--port"][..]),
        "watch" => ("watch [AGENT_ID] [--interval SECONDS]", "Refresh the agent tree until interrupted", &["--interval", "--poll-interval"][..]),
        "await-agent" => ("await-agent AGENT_ID [--timeout SECONDS]", "Wait until an agent stops", &["--timeout"][..]),
        "send-message" => ("send-message FROM TO TYPE [--payload TEXT]", "Send a message", &["--payload"][..]),
        "get-messages" => ("get-messages AGENT_ID [--unread-only] [--limit N]", "List messages", &["--unread-only", "--limit"][..]),
        "mark-messages-read" => ("mark-messages-read AGENT_ID [--message-ids ID ...]", "Mark messages read", &["--message-ids"][..]),
        "create-task" => ("create-task TASK_ID PARENT DESCRIPTION [--depends-on ID ...] [--priority N]", "Create a task", &["--depends-on", "--priority"][..]),
        "assign-task" => ("assign-task TASK_ID AGENT_ID", "Assign a task", &[][..]),
        "update-task-status" => ("update-task-status TASK_ID STATUS [--summary TEXT] [--blocked-by TEXT] [--error TEXT]", "Update a task", &["--summary", "--blocked-by", "--error"][..]),
        "query-tasks" => ("query-tasks QUERY_TYPE [--task-id ID] [--parent-agent-id ID] [--assigned-agent-id ID] [--parent-task-id ID] [--root-task-id ID]", "Query tasks", &["--task-id", "--parent-agent-id", "--assigned-agent-id", "--parent-task-id", "--root-task-id"][..]),
        "create-subtask" => ("create-subtask TASK_ID PARENT_TASK PARENT_AGENT DESCRIPTION [--depends-on ID ...] [--priority N]", "Create a subtask", &["--depends-on", "--priority"][..]),
        "retry-task" => ("retry-task TASK_ID", "Retry a dead-letter task", &[][..]),
        "dead-letter-queue" => ("dead-letter-queue [--limit N]", "List the dead-letter queue", &["--limit"][..]),
        "task-failure-history" => ("task-failure-history TASK_ID", "Show failure history", &[][..]),
        "wait-for-task" => ("wait-for-task TASK_ID [--timeout SECONDS] [--poll-interval SECONDS]", "Wait until a task finishes", &["--timeout", "--poll-interval"][..]),
        "get-available-tasks" => ("get-available-tasks [--agent-id ID]", "List tasks whose dependencies are done", &["--agent-id"][..]),
        "declare-work-intent" => ("declare-work-intent AGENT_ID PATH INTENT [--ttl SECONDS]", "Declare work intent", &["--ttl"][..]),
        "get-work-intents" => ("get-work-intents [--agent-id ID]", "List work intents", &["--agent-id"][..]),
        "clear-work-intent" => ("clear-work-intent AGENT_ID [--document-path PATH]", "Clear a work intent", &["--document-path"][..]),
        "declare-dependency" => ("declare-dependency AGENT DEPENDS_ON [--depends-on-task-id ID] [--condition NAME]", "Declare a dependency", &["--depends-on-task-id", "--condition"][..]),
        "manage-dependencies" => ("manage-dependencies MODE AGENT_ID", "Check or list dependencies", &[][..]),
        "satisfy-dependency" => ("satisfy-dependency DEP_ID", "Mark a dependency satisfied", &[][..]),
        "get-all-dependencies" => ("get-all-dependencies [--dependent-agent-id ID]", "List dependencies", &["--dependent-agent-id"][..]),
        "acquire-coordinator-lease" => ("acquire-coordinator-lease AGENT_ID [--ttl SECONDS]", "Acquire the coordinator lease", &["--ttl"][..]),
        "refresh-coordinator-lease" => ("refresh-coordinator-lease AGENT_ID", "Refresh the coordinator lease", &[][..]),
        "release-coordinator-lease" => ("release-coordinator-lease AGENT_ID", "Release the coordinator lease", &[][..]),
        "get-leader" => ("get-leader", "Show the coordinator lease holder", &[][..]),
        "claim-leadership" => ("claim-leadership AGENT_ID [--ttl SECONDS]", "Claim leadership", &["--ttl"][..]),
        "leader-status" => ("leader-status", "Show whether a leader is active", &[][..]),
        "ha-dashboard" => ("ha-dashboard", "Show the coordinator lease", &[][..]),
        "spawn-subagent" => ("spawn-subagent PARENT TYPE [--description TEXT] [--prompt TEXT] [--source NAME]", "Record a pending spawn", &["--description", "--prompt", "--source"][..]),
        "report-subagent-spawned" => ("report-subagent-spawned PARENT CHILD [--subagent-type TYPE] [--source NAME]", "Report that a spawn registered", &["--subagent-type", "--source"][..]),
        "list-pending-spawns" => ("list-pending-spawns PARENT [--all]", "List pending spawns", &["--all"][..]),
        "cancel-spawn" => ("cancel-spawn SPAWN_ID", "Cancel a pending spawn", &[][..]),
        "request-subagent-deregistration" => ("request-subagent-deregistration PARENT CHILD", "Ask a child to stop", &[][..]),
        "await-subagent-stopped" => ("await-subagent-stopped CHILD [--timeout SECONDS]", "Wait until a child stops", &["--timeout"][..]),
        "who" => ("who [status|claim|release|handoff] [AGENT] [AREA] [--to-agent-id ID] [--ttl SECONDS] [--note TEXT]", "Show ownership or claim an area", &["--action", "--agent-id", "--area", "--to-agent-id", "--ttl", "--note"][..]),
        _ => return None,
    };
    let mut text = format!("usage: coordinationhub {usage}\n\n{about}\n");
    if !flags.is_empty() {
        text.push_str("\nflags:\n");
        for flag in flags {
            text.push_str(&format!("  {flag}\n"));
        }
    }
    text.push_str("\nshared flags: --json --storage-dir PATH --project-root PATH --namespace NAME\n");
    Some(text)
}
